create table if not exists public.election_governance_assurance_reporting_metrics(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,report_id uuid references public.election_governance_assurance_reports(id) on delete set null,report_version integer,open_findings integer not null default 0,high_critical_findings integer not null default 0,overdue_findings integer not null default 0,verified_findings integer not null default 0,closure_rate integer not null default 0 check(closure_rate between 0 and 100),active_reviews integer not null default 0,reporting_status text,recorded_at timestamptz not null default now());
create index if not exists assurance_reporting_metrics_idx on public.election_governance_assurance_reporting_metrics(award_space_id,recorded_at desc);
alter table public.election_governance_assurance_reporting_metrics enable row level security;
